import{_ as e,c as a,o as s,a3 as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/configuration/index.md","filePath":"master/services/project/configuration/index.md","lastUpdated":1792041590000}'),r={name:"master/services/project/configuration/index.md"};function n(i,t,l,c,d,h){return s(),a("div",null,t[0]||(t[0]=[o(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Configuration holds the small lists that other Project pages draw from. You set them up once, then pick from them when you create projects and tasks. This group covers tags and activity plans. Stages and milestones have their own pages.</p><blockquote><p><strong>In simple words:</strong> Configuration is the set of labels and checklists your team reuses on every project and task.</p></blockquote><p>Open <code>Project → Configurations</code>. The menu also holds <strong>Project Stages</strong>, <strong>Task Stages</strong> and <strong>Milestones</strong>. Those belong to the project and task flow.</p><h2 id="what-each-list-does" tabindex="-1">What each list does <a class="header-anchor" href="#what-each-list-does" aria-label="Permalink to &quot;What each list does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>List</th><th>Used for</th></tr></thead><tbody><tr><td><a href="./tags.html">Tags</a></td><td>Coloured labels on projects and tasks for grouping and filtering</td></tr><tr><td><a href="./activity-plans.html">Activity plans</a></td><td>Ready-made sets of follow-up activities you start from Chatter</td></tr><tr><td>Project Stages and Milestones</td><td>The steps and key points of a project. See <a href="./../project-management/project-stages-and-milestones.html">Project stages and milestones</a></td></tr><tr><td>Task Stages</td><td>The steps of tasks inside one project. See <a href="./../task-management/task-stages-and-states.html">Task stages and states</a></td></tr></tbody></table><h2 id="how-they-connect" tabindex="-1">How they connect <a class="header-anchor" href="#how-they-connect" aria-label="Permalink to &quot;How they connect&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tag  ──►  shown on  Project and Task cards, used in filters</span></span>
<span class="line"><span>Activity plan  ──►  started from the Chatter of a Project or Task</span></span></code></pre></div><h2 id="suggested-order" tabindex="-1">Suggested order <a class="header-anchor" href="#suggested-order" aria-label="Permalink to &quot;Suggested order&quot;">​</a></h2><ol><li>Create the tags your team needs, such as <strong>Design</strong> or <strong>Client Work</strong>.</li><li>Create activity plans for routines you repeat, such as a launch checklist.</li><li>Use the tags and plans when you <a href="./../project-management/create-project.html">create a project</a> or <a href="./../task-management/create-task.html">create a task</a>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Archive a tag or plan with <strong>Delete</strong> when you stop using it. <strong>Restore</strong> brings it back. <strong>Force delete</strong> removes it for good.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./tags.html">Tags</a></li><li><a href="./activity-plans.html">Activity plans</a></li><li><a href="./../get-started/project-settings.html">Project settings</a></li><li><a href="./../../../getting-started/chatter.html">Chatter</a></li></ul>`,13)]))}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
